/* بيانات قسم nabat: تُحمَّل عند أول فتح للقسم */
window.NABAT = {"p":[{"id":"zt","n":"الزيتون والتين","intro":"أقسم الله بالتين والزيتون، وجعل الزيتونة شجرة تخرج من طور سيناء تنبت بالدهن، وضرب بزيتها مثلاً لنوره في قلب المؤمن؛ فالنبات هنا آية ونور، لا غذاء وحده.","eps":[{"t":"القسم بالتين والزيتون","r":[95,1,4]},{"t":"شجرة تخرج من طور سيناء","r":[23,20,20]},{"t":"الزيتونة في مثل النور","r":[24,35,35]}],"ls":[{"t":"شجرة الزيتون من طور سيناء: دهن وإدام","r":[23,20,20],"q":{"bk":"saadi","w":"السعدي","s":23,"ay":20,"x":"{20}{وشجرة تخرج من طور سَيۡناءَ}: وهي شجرة الزيتون؛ أي: جنسها، خُصَّت بالذكر لأنَّ مكانها خاصٌّ في أرض الشام، ولمنافعها التي ذُكِرَ بعضُها في قوله:{تَنۡبُتُ بالدُّهن وصِبۡغٍ للآكلين}؛ أي: فيها الزيت الذي هو دهنٌ، يُسْتَعْمَلُ استعمالَه من الاستصباح به، واصطباغ للآكلين؛ أي: يجعل إداماً للآكلين وغير ذلك من المنافع.","en":"Al-Sa'di: the olive tree is singled out because its place is specific to the land of Sham and for its benefits, some of which are mentioned in \"it grows with oil and a relish for those who eat\": its oil is burned for light, and it is used as a condiment for those who eat, among other benefits."}},{"t":"زيتونة لا شرقية ولا غربية: صفاء الزيت","r":[24,35,35],"q":{"bk":"saadi","w":"السعدي","s":24,"ay":35,"x":"وإذا انتفى عنها الأمران؛ كانت متوسطةً من الأرض؛ كزيتون الشام؛ تصيبُه الشمس أول النهار وآخره، فَيَحْسُنُ ويَطيبُ ويكونُ أصفى لزيتها، ولهذا قال:{يكادُ زيتُها}: من صفائه {يضيءُ ولو لم تمسَسۡهُ نارٌ}: فإذا مسَّتْه النار؛ أضاء إضاءةً بليغةً.","en":"Al-Sa'di: when it is neither extreme it is moderate in the land, like the olive of Sham, which the sun touches at the start and the end of the day, so it becomes fine and good and its oil purer; hence \"its oil would almost glow though no fire touched it\", and when fire touches it, it lights brilliantly."}},{"t":"زيت الفطرة الصافية يشتعل بنور الإيمان","r":[24,35,35],"q":{"bk":"saadi","w":"السعدي","s":24,"ay":35,"x":"ووجه هذا المثل الذي ضربه الله وتطبيقُه على حالةِ المؤمن ونورِ الله في قلبه أنَّ فطرتَه التي فُطِرَ عليها بمنزلة الزيتِ الصافي؛ ففطرتُه صافيةٌ مستعدَّة للتعاليم الإلهية والعمل المشروع؛ فإذا وصل إليه العلم والإيمان؛ اشتعل ذلك النور في قلبه بمنزلة اشتعال النار في فتيلةِ ذلك المصباح، وهو صافي القلب من سوء القصدِ وسوء الفهم عن الله، إذا وصل إليه الإيمان؛ أضاء إضاءةً عظيمةً لصفائِهِ من الكُدورات، وذلك بمنزلة صفاء الزُّجاجة الدُّرِّيَّةِ، فيجتمع له نورُ الفطرة ونورُ الإيمان ونورُ العلم وصفاء المعرفة نورٌ على نورِهِ.","en":"Al-Sa'di on applying the parable: the believer's innate nature is like pure oil, ready for divine teaching and lawful action; when knowledge and faith reach it, the light kindles in his heart as fire kindles the wick, so he gathers the light of nature, of faith, of knowledge and of clear understanding, \"light upon light\"."}},{"t":"ما أقسم الله عليه بالتين والزيتون","r":[95,1,4],"q":{"bk":"saadi","w":"السعدي","s":95,"ay":1,"x":"{4} والمقسم عليه قوله: {لقد خَلَقۡنا الإنسان في أحسنِ تقويمٍ}؛ أي: تامَّ الخلق، متناسب الأعضاء، منتصب القامة، لم يفقد ممَّا يحتاج إليه ظاهراً وباطناً شيئاً.","en":"Al-Sa'di: what is sworn upon is \"We created man in the best of forms\", that is, perfectly formed, well-proportioned, upright in stature, lacking nothing he needs outwardly or inwardly."}}]},{"id":"nk","n":"النخل","intro":"ذُكر النخل في جذع النخلة الذي أُمرت مريم بهزّه، وفي النخل الباسقات ذات الطلع النضيد، وفي قنوان النخل الدانية، وفي جنات النخيل والأعناب؛ ثم ربط الحديث الصحيح بين النخلة والمسلم.","eps":[{"t":"هزّ جذع النخلة","r":[19,23,26]},{"t":"النخل الباسقات","r":[50,10,11]},{"t":"قنوان دانية","r":[6,99,99]},{"t":"جنات النخيل والأعناب","r":[36,34,34]}],"ls":[{"t":"هُزّي إليك بجذع النخلة تساقط عليك رطباً جنياً","r":[19,25,26],"q":{"bk":"saadi","w":"السعدي","s":19,"ay":23,"x":"{25}{وهُزِّي إليك بجذع النخلةِ تُساقِطۡ عليك رُطَباً جنيًّا}؛ أي: طريًّا لذيذاً نافعاً. {26}{فكُلي}: من التمر، {واشۡربي}: من النهر، {وقَرِّي عَيۡناً}: بعيسى؛ فهذا طمأنينتها من جهة السلامة من ألم الولادة وحصول المأكل والمشرب الهنيِّ، وأما من جهة قالة الناس؛ فأمرها أنَّها إذا رأت أحداً من البشر أنْ تقولَ على وجه الإشارة:{إنِّي نذرتُ للرحمن صوماً}؛ أي: سكوتاً، {فلن أكلِّمَ اليوم إنسيًّا}؛ أي: لا تخاطبيهم بكلام لتستريحي من قولهم وكلامهم، وكان معروفاً عندهم أنَّ السكوت من العبادات المشروعة.","en":"Al-Sa'di: \"shake the trunk of the palm toward you, it will drop upon you ripe fresh dates\" — fresh, delicious and beneficial; \"so eat\" of the dates, \"and drink\" from the stream, \"and be comforted\" by Jesus; that was her reassurance about safety from the pain of childbirth and about pleasant food and drink. As for people's talk, she was told to say to anyone she saw that she had vowed silence to the Merciful, so she should not address them and could rest from their words, silence being a recognised act of worship among them."}},{"t":"النخل الباسقات رزقاً للعباد","r":[50,10,11],"q":{"bk":"saadi","w":"السعدي","s":50,"ay":10,"x":"{8 ـ 11} وخصَّ من تلك المنافع [بالذكر] الجنَّات المشتملة على الفواكه اللَّذيذة من العنب والرُّمان والأترجِّ والتُّفاح وغير ذلك من أصناف الفواكه، ومن النخيل الباسقات؛ أي: الطوال، التي يطول نفعها ، وترتفع إلى السماء حتى تبلغ مبلغاً لا يبلغه كثيرٌ من الأشجار، فتخرجَ من الطلع النضيد في قنوانها ما هو رزقٌ للعباد قوتاً وأدماً وفاكهةً يأكلون منه ويدَّخرون هم ومواشيهم.","en":"Al-Sa'di: of those benefits Allah singled out gardens full of delicious fruits — grapes, pomegranates, citron, apples and other fruits — and the tall date palms whose benefit lasts long and which rise toward the sky higher than many trees, bringing out of the layered spathe in their clusters provision for the servants as staple, relish and fruit, which they eat and store, they and their animals."}},{"t":"قنوان دانية: ثمر قريب التناول","r":[6,99,99],"q":{"bk":"saadi","w":"السعدي","s":6,"ay":99,"x":"{ومن النخل}: أخرج اللهُ {من طَلۡعِها}: وهو الكُفُرَّى والوعاء قبل ظهور القنو منه، فيخرج من ذلك الوعاء {قِنۡوانٌ دانيةٌ}؛ أي: قريبة سهلة التناول متدلية على من أرادها؛ بحيث لا يعسُرُ التناول من النخل، وإن طالت؛ فإنه يوجد فيها كَرَبٌ ومراقي يَسْهُلُ صعودها.","en":"Al-Sa'di: \"from the palm, from its spathe\" — the sheath before the cluster appears — come \"low-hanging clusters\", close and easy to reach, hanging down for whoever wants them, so that picking from the palm is not hard even when it grows tall, for it has stubs and steps that make climbing easy."}},{"t":"النخل ذات الأكمام: قوت يُدّخر وفاكهة","r":[55,10,12],"q":{"bk":"saadi","w":"السعدي","s":55,"ay":12,"x":"ثم ذكر ما فيها من الأقوات الضرورية، فقال: {11}{فيها فاكهةٌ}: وهي جميع الأشجار التي تثمر الثمراتِ التي يتفكَّه بها العبادُ من العنب والتين والرمان والتُّفاح وغير ذلك، {والنَّخۡلُ ذاتُ الأكمام}؛ أي: ذات الوعاء الذي ينفلق عن القِنْوان التي تَخْرُجُ شيئاً فشيئاً حتى تتمَّ فتكون قوتاً يدَّخر ويؤكل ويتزوَّد منه المقيم والمسافر وفاكهةً لذيذةً من أحسن الفواكه.","en":"Al-Sa'di: \"therein is fruit\" — all the trees that bear fruit the servants enjoy, such as grapes, figs, pomegranates and apples — \"and palm trees having sheaths\", the sheath that splits to show the clusters, which emerge little by little until complete, becoming a staple that is stored, eaten and carried as provision by resident and traveller, and a delicious fruit among the best."}},{"t":"نخلٌ وأعناب بعد موت الأرض","r":[36,33,34],"q":{"bk":"saadi","w":"السعدي","s":36,"ay":33,"x":"{34}{وجَعَلۡنا فيها}؛ أي: في تلك الأرض الميتة {جَنَّاتٍ}؛ أي: بساتين فيها أشجارٌ كثيرةٌ، وخصوصاً النخيل والأعناب، اللذان هما أشرف الأشجار، {وفجَّرۡنا فيها}؛ أي: في الأرض {من العيون}: جعلنا في الارض تلكَ الأشجارَ والنخيل والأعناب.","en":"Al-Sa'di: \"and We placed therein gardens\" — orchards with many trees, especially palms and vines, the noblest of trees — \"and caused springs to gush forth therein\"."}},{"t":"الشجرة الطيبة: قول ابن مسعود","r":[14,24,25],"q":{"bk":"ibnkathir","w":"ابن كثير","s":14,"ay":24,"x":"وَهَكَذَا رَوَاهُ السُّدِّي، عَنْ مُرَّة، عَنِ ابْنِ مَسْعُودٍ قَالَ: هِيَ النَّخْلَةُ.","en":"Ibn Kathir: this is how al-Suddi narrated it from Murra from Ibn Mas'ud, who said: it is the palm."}}]},{"id":"ar","n":"العنب والرمان والجنات","intro":"جنات من أعناب وزيتون ورمان، متشابهة في الشجر وغير متشابهة في الثمر، تُسقى بماء واحد؛ يذكرها القرآن بعد أن يعمّ النبات كله، ليُنظر إليها ويُتفكَّر فيها ويُشكر منشئها.","eps":[{"t":"جنات من أعناب والزيتون والرمان","r":[6,99,99]},{"t":"متشابهاً وغير متشابه","r":[6,141,141]},{"t":"أنبتنا فيها من كل زوج بهيج","r":[50,7,11]}],"ls":[{"t":"أشجار كثيرة النفع خُصّت بالذكر","r":[6,99,99],"q":{"bk":"saadi","w":"السعدي","s":6,"ay":99,"x":"{و}: أخرج تعالى بالماء {جناتٍ من أعناب والزيتون والرمان}: فهذه من الأشجار الكثيرة النفع العظيمة الوقع؛ فلذلك خصَّصها الله بالذِّكر بعد أن عمَّ جميع الأشجار والنوابت.","en":"Al-Sa'di: \"and gardens of grapes, olives and pomegranates\" — these are trees of great benefit and weighty effect, so Allah singled them out after having covered all trees and plants."}},{"t":"متشابه في المنظر وغير متشابه في الطعم","r":[6,141,141],"q":{"bk":"ibnkathir","w":"ابن كثير","s":6,"ay":141,"x":"وَقَالَ ابْنُ جُرَيْج: ﴿مُتَشَابِهًا وَغَيْرَ مُتَشَابِهٍ﴾ قَالَ: متشابه فِي الْمَنْظَرِ، وَغَيْرَ مُتَشَابِهٍ فِي الطَّعْمِ.","en":"Ibn Kathir: Ibn Jurayj said of \"alike and unlike\": alike in appearance, and unlike in taste."}},{"t":"ولماذا أنشأها الله: لمنافع العباد","r":[6,141,141],"q":{"bk":"saadi","w":"السعدي","s":6,"ay":141,"x":"{و} أنشأ تعالى {الزيتونَ والرُّمانَ متشابهاً}: في شجره، {وغير متشابهٍ}: في ثمره وطعمه، كأنه قيل: لأي شيء أنشأ الله هذه الجنات؟ وما عطف عليها؟ فأخبر أنه أنشأها لمنافع العباد، فقال:{كلوا من ثمرِهِ}؛ أي: النخل والزرع، {إذا أثمر وآتوا حَقَّه يومَ حصادِهِ}؛ أي: أعطوا حقَّ الزرع، وهو الزكاة ذات الأنصباء المقدَّرة في الشرع؛ أمرهم أن يعطوها يوم حصادها، وذلك لأنَّ حصادَ الزرع بمنزلة حَوَلان الحول؛ لأنه الوقت الذي تتشوَّف إليه نفوس الفقراء، ويسهُلُ حينئذٍ إخراجُه على أهل الزرع، ويكون الأمر فيها ظاهراً لمن أخرجها حتى يتميَّز المخرِج ممَّن لا يخرج.","en":"Al-Sa'di: \"and the olive and the pomegranate, alike\" in their trees, \"and unlike\" in fruit and taste — as if it were asked, for what did Allah bring forth these gardens, and what is joined to them? He informed that He brought them forth for the benefit of the servants, saying \"eat of its fruit when it bears fruit and give its due on the day of harvest\": the due of the crop, which is the zakah with its legally fixed thresholds, to be given on harvest day, because harvest is like the passing of the year; it is the time the poor look forward to, it is easy for the owners then, and it shows plainly who gives and who does not."}},{"t":"من كل صنف بهيج تسرّ الناظرين","r":[50,7,8],"q":{"bk":"saadi","w":"السعدي","s":50,"ay":10,"x":"{وأنبَتۡنا فيها من كلِّ زوجٍ بهيجٍ}؛ أي: من كل صنفٍ من أصناف النبات التي تسرُّ ناظريها، وتُعْجِب مبصريها، وتُقِرُّ عين رامقيها لأكل بني آدم وأكل بهائمهم ومنافعهم.","en":"Al-Sa'di: \"and We caused to grow therein of every beautiful kind\" — every kind of plant that pleases its beholders, delights its observers and refreshes the eyes of those who gaze, for the food of the children of Adam and of their animals, and their benefits."}}]},{"id":"hb","n":"الحب والزرع والسنابل","intro":"الحبّ وما يُحرث ويُزرع: مثلٌ للإنفاق المضاعف في حبة تنبت سبع سنابل، ودليلٌ على أن الإنبات من الله لا من الحارث، وفيه حقٌّ يُؤدّى يوم الحصاد.","eps":[{"t":"مثل حبة أنبتت سبع سنابل","r":[2,261,261]},{"t":"أفرأيتم ما تحرثون","r":[56,63,67]},{"t":"وآتوا حقه يوم حصاده","r":[6,141,141]},{"t":"فالق الحب والنوى","r":[6,95,95]}],"ls":[{"t":"أأنتم تزرعونه أم نحن الزارعون؟","r":[56,63,65],"q":{"bk":"saadi","w":"السعدي","s":56,"ay":63,"x":"أم أنتم الذين أخرجتم سُنْبله وثمرَه حتى صار حبًّا حصيداً وثمراً نضيجاً؟ أم الله الذي انفرد بذلك وحدَه وأنعم به عليكم، وأنتم غايةُ ما تفعلون أن تحرُثوا الأرض، وتشقُّوها، وتُلْقوا فيها البذرَ، ثم لا علم عِندكم بما يكون بعد ذلك ولا قدرةَ لكم على أكثر من ذلك؟","en":"Al-Sa'di: is it you who brought out its ear and its fruit until it became harvestable grain and ripe fruit, or is it Allah who alone did that and bestowed it on you, while the most you do is plough the earth, split it and throw seed in it, then you have no knowledge of what follows and no power to do more?"}},{"t":"لو نشاء لجعلناه حطاماً","r":[56,65,67],"q":{"bk":"saadi","w":"السعدي","s":56,"ay":63,"x":"ومع ذلك؛ فنبَّههم على أنَّ ذلك الحرثَ معرضٌ للأخطار لولا حفظُ الله وإبقاؤه بُلغةً لكم ومتاعاً إلى حين. فقال:{لو نشاء لجعلناه}؛ أي: الزرع المحروث وما فيه من الثمار {حُطاماً}؛ أي: فتاتاً متحطِّماً لا نفع فيه ولا رزق، {فظَلۡتُمۡ}؛ أي: فصرتُم بسبب جعله حطاماً بعد أن تعبتم فيه، وأنفقتم النفقات الكثيرة، {تَفَكَّهونَ}؛ أي: تندمون وتحسرون على ما أصابكم، ويزول بذلك فرحُكم وسرورُكم وتفكُّهكم، فتقولون:{إنَّا لَمُغۡرَمونَ}؛ أي: إنَّا قد نقصنا وأصابتنا مصيبةٌ اجتاحَتْنا.","en":"Al-Sa'di: He warned them that the sown field is exposed to dangers were it not for Allah's keeping it as sustenance and enjoyment for a while: \"if We willed, We would make it debris\", crumbled and useless, so you would be left, after toiling and spending much on it, saying \"we are indeed burdened with debt\"."}},{"t":"حق الزرع يوم حصاده: الزكاة","r":[6,141,141],"q":{"bk":"saadi","w":"السعدي","s":6,"ay":141,"x":"وفي هذه الآية دليلٌ على وجوب الزكاة في الثمار، وأنه لا حَوْلَ لها، بل حولُها حصادُها في الزروع وجذاذ النخيل، وأنه لا تتكرَّر فيها الزكاة لو مكثت عند العبد أحوالاً كثيرةً إذا كانت لغير التجارة؛ لأنَّ الله لم يأمر بالإخراج منه إلاَّ وقتَ حصادِهِ، وأنَّه لو أصابها آفةٌ قبل ذلك بغير تفريط من صاحب الزرع والثمر؛ أنه لا يضمنها، وأنه يجوز الأكل من النخل والزرع قبل إخراج الزكاة منه، وأنه لا يُحْسَبُ ذلك من الزكاة، بل يزكِّي المال الذي يبقى بعده، وقد كان النبي - صلى الله عليه وسلم - يَبْعَثُ خارصاً يخرُصُ للناس ثمارَهم ويأمرُهُ أن يَدَعَ لأهلها الثلث أو الربع بحسب ما يعتريها من الأكل وغيره من أهلها وغيرهم.","en":"Al-Sa'di: this verse is proof that zakah is obligatory on fruits; it has no passing of a year, its year being its harvest for crops and its picking for dates; it is not repeated even if the crop stays with its owner for many years when it is not for trade; the verse commands giving only at harvest time; if a blight strikes it before that, without negligence from the owner, he does not owe it; it is permitted to eat from the palm and the crop before paying zakah and that is not counted toward it, rather he pays zakah on what remains after; and the Prophet used to send an assessor to estimate people's fruit, and told him to leave for them a third or a quarter for what befalls the fruit of eating and the like."}},{"t":"قنو يُعلَّق في المسجد للمساكين","r":[6,141,141],"q":{"bk":"ibnkathir","w":"ابن كثير","s":6,"ay":141,"x":"وَقَدْ رَوَى الْإِمَامُ أَحْمَدُ وَأَبُو دَاوُدَ فِي سُنَنِهِ مِنْ حَدِيثِ مُحَمَّدِ بْنِ إِسْحَاقَ: حَدَّثَنِي مُحَمَّدُ بْنُ يَحْيَى ابن حبَّان، عَنْ عَمِّهِ وَاسِعِ بْنِ حَبَّانَ، عَنْ جَابِرُ بْنُ عَبْدِ اللَّهِ؛ أَنَّ النَّبِيَّ ﷺ أمَرَ مِنْ كُل جَادٍّ عَشْرَة أوسُق مِنَ التَّمْرِ، بقنْو يُعَلَّقُ فِي الْمَسْجِدِ لِلْمَسَاكِينِ وَهَذَا إِسْنَادُهُ جَيِّدٌ قَوِيٌّ.","en":"Ibn Kathir: Imam Ahmad and Abu Dawud narrated, from the hadith of Muhammad ibn Ishaq, from Jabir ibn Abdullah, that the Prophet ordered that from every ten wasqs of dates a cluster be hung in the mosque for the poor; and its chain is good and strong."}}]},{"id":"ry","n":"العصف والريحان والمرعى","intro":"من النبات ما يأكله الناس، ومنه ما تأكله الأنعام، ومنه ما يُشمّ: الحب ذو العصف والريحان، والأبّ متاعاً لكم ولأنعامكم؛ نعمة مضاعفة على الناس والأنعام.","eps":[{"t":"والحب ذو العصف والريحان","r":[55,10,13]},{"t":"وفاكهة وأبّاً متاعاً لكم ولأنعامكم","r":[80,28,32]},{"t":"أخرج منها ماءها ومرعاها","r":[79,31,33]}],"ls":[{"t":"الحب ذو العصف والريحان","r":[55,12,12],"q":{"bk":"saadi","w":"السعدي","s":55,"ay":12,"x":"{12}{والحبُّ ذو العصفِ}؛ أي: ذو الساق الذي يُداس فينتفع بتبنه للأنعام وغيرها، ويدخل في ذلك حبُّ البُرِّ والشعير والذُّرة والأرز والدخن وغير ذلك، {والريحانُ}: يُحتمل أنَّ المراد به جميع الأرزاق التي يأكلها الآدميُّون، فيكون هذا من باب عطف العامِّ على الخاصِّ، ويكون الله [تعالى] قد امتنَّ على عباده بالقوت والرزق عموماً وخصوصاً.","en":"Al-Sa'di: \"and grain with husk\" — the stalk that is threshed and whose chaff benefits the animals and others, including grains of wheat, barley, millet, rice and others; \"and the fragrant herb\" may mean all the provisions that people eat, so it is mentioning the general after the particular, and Allah has reminded His servants of staple and provision in general and in particular."}},{"t":"الريحان: روائح طيبة تنشرح لها النفوس","r":[55,12,12],"q":{"bk":"saadi","w":"السعدي","s":55,"ay":12,"x":"ويُحتمل أنَّ المراد بالريحان الريحان المعروف، وأنَّ الله امتنَّ على عباده بما يسَّره في الأرض من أنواع الروائح الطيبة والمشامِّ الفاخرة التي تسرُّ الأرواح وتنشرح لها النفوس.","en":"Al-Sa'di: it may be that the fragrant herb means the known herb, and that Allah favoured His servants with the kinds of good scents and splendid fragrances He made easy on the earth, which delight the spirits and open the hearts."}},{"t":"الأبّ متاعاً لكم ولأنعامكم","r":[80,31,32],"q":{"bk":"saadi","w":"السعدي","s":80,"ay":24,"x":"والأبُّ ما تأكله البهائم والأنعام، ولهذا قال:{متاعاً لكم ولأنعامكم}: التي خلقها الله وسخَّرَها لكم.","en":"Al-Sa'di: the abb is what beasts and livestock eat, hence He said \"as provision for you and your livestock\", which Allah created and subjected to you."}}]},{"id":"sd","n":"السدر والطلح والأثل","intro":"ذُكر السدر في الجنة مخضوداً، وسدرة المنتهى في الأفق الأعلى، وذُكر الخمط والأثل وقليل من سدر في عقوبة أهل سبأ؛ فشجرٌ معروف يرد في مقام الإكرام وفي مقام العبرة.","eps":[{"t":"سدر مخضود وطلح منضود","r":[56,27,33]},{"t":"سدرة المنتهى","r":[53,13,18]},{"t":"بدّلناهم بجنتيهم جنتين","r":[34,15,16]}],"ls":[{"t":"ظلٌّ ظليل في سدر مخضود وطلح منضود","r":[56,28,29],"q":{"bk":"saadi","w":"السعدي","s":56,"ay":28,"x":"وللسِّدْرِ من الخواصِّ الظلُّ الظَّليل وراحة الجسم فيه، {وطلحٍ منضودٍ}: والطَّلْح معروفٌ، وهو شجرٌ كبارٌ يكون بالبادية تُنَضَّدُ أغصانه من الثمر اللذيذ الشهي، {وماءٍ مسكوبٍ}؛ أي: كثير من العيون والأنهار السارحة والمياه المتدفِّقة، {وفاكهةٍ كثيرةٍ.","en":"Al-Sa'di: the lote has among its properties deep shade and ease for the body in it; \"and layered talh\": the talh is known, a large tree of the desert whose branches are layered with delicious desirable fruit; \"and extended water\" — many streams and flowing waters — \"and abundant fruit\"."}},{"t":"سدر الدنيا كثير الشوك وسدر الآخرة بلا شوك","r":[56,27,27],"q":{"bk":"ibnkathir","w":"ابن كثير","s":56,"ay":27,"x":"وَالظَّاهِرُ أَنَّ الْمُرَادَ هَذَا وَهَذَا فَإِنَّ سِدْرَ الدُّنْيَا كَثِيرُ الشَّوْكِ قَلِيلُ الثَّمَرِ، وَفِي الْآخِرَةِ عَلَى عَكْسٍ مِنْ هَذَا لَا شَوْكَ فِيهِ، وَفِيهِ الثَّمَرُ الْكَثِيرُ الَّذِي قَدْ أَثْقَلَ أَصْلَهُ، كَمَا قَالَ الْحَافِظُ أَبُو بَكْرِ بْنُ سَلْمَانَ النَّجَّادُ.","en":"Ibn Kathir: the apparent meaning is both; the lote of this world is full of thorns and little fruit, while in the Hereafter it is the reverse: no thorn in it, and plentiful fruit that weighs down its trunk, as al-Hafiz Abu Bakr ibn Salman al-Najjad said."}},{"t":"سدرة المنتهى شجرة فوق السماء السابعة","r":[53,13,14],"q":{"bk":"saadi","w":"السعدي","s":53,"ay":14,"x":"{13 ـ 14} ولهذا قال: {ولقد رآه نزلةً أخرى}؛ أي: رأى محمدٌ جبريل مرةً أخرى نازلاً إليه، {عند سِدۡرَةِ المُنتَهى}: وهي شجرةٌ عظيمةٌ جدًّا فوق السماء السابعة، سميت سدرةَ المنتهى؛ لأنَّه ينتهي إليها ما يعرج من الأرض، وينزل إليها ما ينزل من الله من الوحي وغيره، أو لانتهاء علم المخلوقات إليها؛ أي: لكونها فوق السماواتِ والأرض؛ فهي المنتهى في علومها، أو لغير ذلك.","en":"Al-Sa'di: \"he saw him on another descent, at the Lote-tree of the Utmost Boundary\": a very great tree above the seventh heaven, called the Utmost Boundary because what ascends from earth ends there and what descends from Allah of revelation and other things arrives there, or because the knowledge of the creatures ends there, being above the heavens and the earth, or for another reason."}},{"t":"عندها جنة المأوى","r":[53,15,15],"q":{"bk":"saadi","w":"السعدي","s":53,"ay":14,"x":"{15} عند تلك الشجرة، {جنَّة المأوى}؛ أي: الجنة الجامعة لكلِّ نعيم؛ بحيث كانت محلًّا تنتهي إليه الأماني، وترغب فيها الإرادات، وتأوي إليها الرغبات.","en":"Al-Sa'di: \"near it is the Garden of Refuge\" — the garden that gathers every delight, a place where hopes end, desires aspire and wishes take shelter."}},{"t":"بُدّلوا بجنتيهم خمطاً وأثلاً وشيئاً من سدر قليل","r":[34,16,16],"q":{"bk":"saadi","w":"السعدي","s":34,"ay":16,"x":"ولهذا قال:{وبدَّلۡناهم بجنَّتَيۡهم جنتينِ ذواتي أكُل}؛ أي: شيءٍ قليل من الأكل الذي لا يقع منهم موقعاً، {خَمۡطٍ وأثۡلٍ وشيءٍ من سدرٍ قليل}: وهذا كله شجرٌ معروفٌ، وهذا من جنس عملهم؛ فكما بدَّلوا الشكر الحسن بالكفر القبيح؛ بُدِّلُوا تلك النعمة بما ذكر.","en":"Al-Sa'di: \"and We replaced their two gardens with two gardens of bitter fruit\" — a little food that does not fall well with them — \"and tamarisk and a few lote trees\"; all of these are known trees, and it matches their deed: as they replaced good gratitude with ugly ingratitude, they were replaced that blessing with what is mentioned."}}]},{"id":"yq","n":"اليقطين","intro":"أنبت الله على يونس عليه السلام شجرة من يقطين بعد أن نبذه الحوت بالعراء وهو سقيم؛ نبتة رحمة وستر تأتي بعد الابتلاء والتسبيح.","eps":[{"t":"فلولا أنه كان من المسبحين","r":[37,139,144]},{"t":"فنبذناه بالعراء وهو سقيم","r":[37,145,145]},{"t":"وأنبتنا عليه شجرة من يقطين","r":[37,146,148]}],"ls":[{"t":"بتسبيحه نجّاه الله من بطن الحوت","r":[37,143,144],"q":{"bk":"saadi","w":"السعدي","s":37,"ay":146,"x":"{143 ـ 144}{فلولا أنَّه كان من المسبِّحينَ}؛ أي: في وقتِه السابقِ بكثرةِ عبادته لربِّه وتسبيحِهِ وتحميدِهِ وفي بطن الحوت حيث قال: {لا إله إلا أنت سبحانَكَ إنِّي كُنۡتُ من الظالمين}؛ {لَلَبِثَ في بطنِهِ إلى يوم يُبۡعَثونَ}؛ أي: لكانتْ مقبرتَهَ، ولكن بسبب تسبيحِهِ وعبادتِهِ لله؛ نجَّاه الله تعالى، وكذلك ينجي الله المؤمنين عند وقوعهم في الشدائد.","en":"Al-Sa'di: \"had he not been of those who glorify\" — in his earlier time by his much worship, glorification and praise of his Lord, and in the belly of the whale when he said \"there is no god but You, glory be to You, I was among the wrongdoers\" — \"he would have remained in its belly until the Day they are resurrected\", it would have been his grave; but because of his glorification and worship of Allah He saved him, and so Allah saves the believers when they fall into hardships."}},{"t":"نبذه بالعراء وهو سقيم","r":[37,145,145],"q":{"bk":"saadi","w":"السعدي","s":37,"ay":146,"x":"{وهو سقيمٌ}؛ أي: قد سَقِمَ ومَرِضَ بسبب حبسِهِ في بطن الحوت حتى صار مثل الفرخ الممعوط من البيضة.","en":"Al-Sa'di: \"and he was ill\" — he had fallen sick because of being confined in the belly of the whale until he was like a chick pulled from its egg."}},{"t":"شجرة اليقطين: ظلٌّ ظليل ولطف","r":[37,146,146],"q":{"bk":"saadi","w":"السعدي","s":37,"ay":146,"x":"{146}{وأنبَتۡنا عليه شجرةً من يَقۡطينٍ}: تُظِلُّه بظلِّها الظليل؛ لأنَّها باردةُ الظِّلال، ولا يسقُطُ عليها ذبابٌ، وهذا من لطفِهِ به وبرِّه.","en":"Al-Sa'di: \"and We caused to grow over him a gourd plant\" — shading him with its deep shade, because it has cool shade and no fly settles on it, and this was from His gentleness to him and His kindness."}}]},{"id":"zq","n":"شجرة الزقوم","intro":"الشجرة الملعونة في القرآن، فتنةٌ للظالمين، تخرج في أصل الجحيم؛ وهي في الآخرة وجهٌ مقابل لما في الجنة من سدر وفاكهة وظلّ.","eps":[{"t":"أذلك خير نزلاً أم شجرة الزقوم","r":[37,62,68]},{"t":"إن شجرة الزقوم طعام الأثيم","r":[44,43,46]},{"t":"لآكلون من شجر من زقوم","r":[56,51,56]},{"t":"والشجرة الملعونة في القرآن","r":[17,60,60]}],"ls":[{"t":"إنا جعلناها فتنة للظالمين","r":[37,63,64],"q":{"bk":"saadi","w":"السعدي","s":37,"ay":62,"x":"{63 ـ 66}{إنا جعلناها فتنةً}؛ أي: عذاباً ونكالاً {للظَّالمينَ}: أنفسهم بالكفر والمعاصي.","en":"Al-Sa'di: \"We have made it a trial\" — that is a punishment and a deterrent — \"for the wrongdoers\", those who wrong themselves by disbelief and sins."}},{"t":"تخرج في أصل الجحيم","r":[37,64,65],"q":{"bk":"saadi","w":"السعدي","s":37,"ay":62,"x":"{إنها شجرةٌ تخرجُ في أصل الجحيم}؛ أي: وسطه؛ فهذا مخرجُها ومعدِنُها؛ شرُّ المعادن وأسوؤها، وشرُّ المغرس يدل على شرِّ الغراس وخسَّته، ولهذا نبَّهنا الله على شرِّها بما ذكر أين تنبُت به وبما ذكر من صفة ثمرتها، وأنها كرؤوس الشياطينِ؛ فلا تسألْ بعد هذا عن طعمها وما تفعلُ في أجوافهم وبطونهم.","en":"Al-Sa'di: \"it is a tree that comes out in the bottom of Hellfire\" — in its middle; this is its source and its mine, the worst of mines and the worst of places; the worst planting-ground points to the vileness of what is planted, so Allah alerted us to its evil by where it grows and by the description of its fruit — that it is like the heads of devils — so do not ask after this about its taste or what it does in their bellies."}},{"t":"فمالئون منها البطون","r":[37,66,66],"q":{"bk":"saadi","w":"السعدي","s":37,"ay":62,"x":"وليس لهم عنها مندوحةٌ ولا مَعْدِلٌ ، ولهذا قال:{فإنَّهم لآكلونَ منها فمالِئونَ منها البطونَ}: فهذا طعامُ أهل النارِ؛ فبئس الطعامُ طعامُهم.","en":"Al-Sa'di: they have no escape or way out from it, hence \"they will eat from it and fill their bellies with it\"; this is the food of the people of the Fire, and wretched is their food."}},{"t":"هذا نزلهم يوم الدين: الضيافة التي قدّموها لأنفسهم","r":[56,51,56],"q":{"bk":"saadi","w":"السعدي","s":56,"ay":52,"x":"{هذا}: الطعام والشراب {نُزُلُهم}؛ أي: ضيافتهم {يومَ الدِّين}: وهي الضيافة التي قدَّموها لأنفسهم وآثروها على ضيافةِ الله لأوليائه؛ قال تعالى:{إنَّ الذين آمنوا وعَمِلوا الصالحاتِ كانتۡ لهم جنَّاتُ الفِرۡدَوۡسِ نُزُلاً.","en":"Al-Sa'di: \"this is their welcome on the Day of Recompense\" — their hospitality, the hospitality they prepared for themselves and preferred over Allah's hospitality for His friends; Allah said \"those who believed and did righteous deeds, for them are the gardens of Firdaus as a welcome.\""}}]},{"id":"kh","n":"الشجرة المنهي عنها","intro":"شجرة واحدة وسط جنة واسعة نُهي عنها آدم وزوجه، وسمّاها الشيطان شجرة الخلد وملكٍ لا يبلى؛ ابتلاءٌ بحدٍّ واحد، ثم ورق الجنة الذي خصفا عليهما منه.","eps":[{"t":"ولا تقربا هذه الشجرة","r":[2,35,36]},{"t":"ما نهاكما ربكما عن هذه الشجرة","r":[7,19,22]},{"t":"هل أدلك على شجرة الخلد","r":[20,120,122]}],"ls":[{"t":"ما نهاكما ربكما عن هذه الشجرة إلا أن تكونا ملكين","r":[7,20,20],"q":{"bk":"saadi","w":"السعدي","s":7,"ay":19,"x":"{20} فلم يزالا ممتثلينِ لأمر الله حتى تغلغل إليهما عدوُّهما إبليس بمكره، فوسوس لهما وسوسةً خدَعَهما بها وموَّه عليهما وقال:{ما نهكُما ربُّكما عن هذه الشجرة إلَّا أن تكونا مَلَكَيۡن}؛ أي: من جنس الملائكة، {أو تكونا مِنَ الخالدينَ}: كما قال في الآية الأخرى: {هل أدُلُّكَ على شجرةِ الخُلۡدِ وملكٍ لا يَبۡلى}.","en":"Al-Sa'di: they kept obeying Allah's command until their enemy Iblis crept in on them with his scheming, whispered to them and deceived them and said \"your Lord did not forbid you this tree except that you become angels\" — of the kind of the angels — \"or become of the immortals\", as He said in the other verse \"shall I lead you to the tree of immortality and a kingdom that never decays?\"."}},{"t":"هل أدلك على شجرة الخلد وملك لا يبلى؟","r":[20,120,120],"q":{"bk":"saadi","w":"السعدي","s":20,"ay":120,"x":"{120} فلم يزل الشيطانُ يوسوسُ لهما ويُزيِّن أكل الشجرة ويقولُ: {هل أدُلُّك على شجرةِ الخُلۡدِ}؛ أي:[الشجرة] التي مَنْ أكل منها خَلَدَ في الجنة، {ومُلۡكٍ لا يَبۡلى}؛ أي: لا ينقطع إذا أكلتَ منها.","en":"Al-Sa'di: Satan kept whispering to them and making eating from the tree seem fair, saying \"shall I lead you to the tree of immortality\" — the tree from which whoever eats lives forever in the Garden — \"and a kingdom that never decays\", that never ends if you eat of it."}},{"t":"فأكلا من الشجرة فبدت لهما سوآتهما","r":[20,121,121],"q":{"bk":"saadi","w":"السعدي","s":20,"ay":120,"x":"{121} فأتاه بصورة ناصح، وتلطَّف له في الكلام؛ فاغترَّ به آدمُ، فأكلا من الشجرةِ، فسُقِطَ في أيديهما وسَقَطَتْ كسوتُهما، واتَّضحت معصيتُهما، وبدا لكلٍّ منهما سوأة الآخر بعد أن كانا مستورَيْن، وجعلا يَخْصِفان على أنفسهما من ورق أشجار الجنَّة؛ ليستَتِر بذلك، وأصابهما من الخجل ما الله به عليم.","en":"Al-Sa'di: he came to him in the guise of an adviser and spoke gently; Adam was deceived, so they ate of the tree, regret fell upon them, their covering fell away, their disobedience became clear, and each saw the other's private part after they had been covered; they began to stitch together on themselves leaves from the trees of the Garden to cover themselves, and they were struck by shame that only Allah knows."}}]},{"id":"rd","n":"الشجرة التي بويع تحتها","intro":"ذكر القرآن الشجرة موضعاً للبيعة: «لقد رضي الله عن المؤمنين إذ يبايعونك تحت الشجرة»؛ فصار لشجرةٍ واحدة ذكرٌ في آية رضا.","eps":[{"t":"إذ يبايعونك تحت الشجرة","r":[48,18,18]}],"ls":[{"t":"بيعة الرضوان: رضا الله عن المؤمنين","r":[48,18,18],"q":{"bk":"saadi","w":"السعدي","s":48,"ay":18,"x":"وكان سبب هذه البيعة ـ التي يقال لها: بيعةُ الرضوان؛ لرضا الله عن المؤمنين فيها.","en":"Al-Sa'di: the reason for this pledge, which is called the Pledge of Ridwan (pleasure), because of Allah's pleasure with the believers in it."}},{"t":"فأنزل السكينة عليهم وأثابهم فتحاً قريباً","r":[48,18,18],"q":{"bk":"saadi","w":"السعدي","s":48,"ay":18,"x":"{فعلم ما في قُلوبِهم}: من الإيمان، {فأنزلَ السكينةَ عليهم}: شكراً لهم على ما في قلوبهم، زادهم هدىً، وعلم ما في قلوبهم من الجزع من تلك الشروط التي شَرَطَها المشركون على رسولِهِ، فأنزل عليهم السكينة تثبِّتُهم، وتطمئنُّ بها قلوبهم، {وأثابهم فتحاً قريباً}: وهو فتح خيبر، لم يحضُرْه سوى أهل الحديبية، فاختصُّوا بخيبر وغنائمها جزاءً لهم وشكراً على ما فعلوه من طاعة الله تعالى والقيام بمرضاته، {ومغانم كثيرةً يأخُذونها وكانَ الله عزيزاً حكيماً}؛ أي: له العزَّة والقدرة، التي قهر بها الأشياء؛ فلو شاء؛ لانتصر من الكفَّار في كلِّ وقعة تكون بينهم وبين المؤمنين، ولكنَّه حكيمٌ يَبْتلي بعضَهم ببعض ويمتحنُ المؤمنَ بالكافر.","en":"Al-Sa'di: \"and He knew what was in their hearts\" of faith, \"so He sent down tranquillity upon them\" in thanks for what was in their hearts, and He increased them in guidance; He knew their hearts' distress at the conditions the polytheists had imposed on His Messenger, so He sent down tranquillity to steady them and calm their hearts, \"and rewarded them with a near conquest\" — the conquest of Khaybar, which only the people of al-Hudaybiyyah attended, so they were specially given Khaybar and its spoils as reward and thanks for their obedience to Allah and seeking His pleasure, \"and much war-gain that they will take, and Allah is ever Mighty and Wise\": had He willed He would have defeated the disbelievers in every encounter, but He is wise, testing some by others and testing the believer by the disbeliever."}}]}],"sg":[{"t":"إحياء الأرض الهامدة بالنبات: دليل على البعث","r":[22,5,5],"q":{"bk":"saadi","w":"السعدي","s":22,"ay":5,"x":"والدليل الثاني: إحياء الأرض بعد موتها، فقال الله فيه:{وترى الأرض هامدةً}؛ أي: خاشعة مغبرَّةً لا نباتَ فيها ولا خُضرة، {فإذا أنۡزَلۡنا عليها الماء اهتزَّتۡ}؛ أي: تحرَّكت بالنبات، {وَرَبَتۡ}؛ أي: ارتفعت بعد خُشوعها، وذلك لزيادة نباتها، {وأنبتتۡ من كلِّ زوج}؛ أي: صنف من أصناف النبات {بَهيج}؛ أي: يُبْهجُ الناظرين ويسرُّ المتأملين.","en":"Al-Sa'di: the second proof is the reviving of the earth after its death; \"and you see the earth barren\" — humble, dusty, no plant or greenery — \"but when We send down water upon it, it stirs\" — moves with plants — \"and swells\" — rises after its humility, through the growth of its plants — \"and grows of every beautiful kind\", that delights the beholders and pleases those who reflect."}},{"t":"وآية لهم الأرض الميتة أحييناها","r":[36,33,33],"q":{"bk":"saadi","w":"السعدي","s":36,"ay":33,"x":"{33} أي: {وآيةٌ لهم}: على البعثِ والنُّشور والقيام بين يدي الله تعالى للجزاء على الأعمال هذه {الأرضُ المَيۡتَةُ}: أنزل الله عليها المطرَ فأحْياها بعد موتها، {وأخۡرَجۡنا منها حَبًّا فمنه يأكُلونَ}: من جميع أصناف الزُّروع ومن جميع أصناف النباتِ التي تأكُلُه أنعامُهم.","en":"Al-Sa'di: \"and a sign for them\" of resurrection and rising to stand before Allah for recompense of deeds is this \"dead earth\": Allah sent rain on it and revived it after its death, \"and We brought forth from it grain, of which they eat\", of all kinds of crops and of all kinds of plants that their animals eat."}},{"t":"الأرض الخاشعة تهتز وتربو","r":[41,39,39],"q":{"bk":"saadi","w":"السعدي","s":41,"ay":39,"x":"{39}{ومن آياتِهِ}: الدالَّة على كمال قدرته وانفراده بالمُلك والتَّدبير والوحدانيَّة، {أنَّك ترى الأرضَ خاشعةً}؛ [أي]: لا نباتَ فيها، {فإذا أنزلۡنا عليها الماءَ}؛ أي: المطر، {اهتزَّتۡ}؛ أي: تحرَّكت بالنبات، {وَرَبَتۡ}: ثم أنبتت من كلِّ زوج بهيج؛ فحيي بها العبادُ والبلادُ. {إنَّ الذي أحياها}: بعد موتها وهمودها {لَمُحيي الموتى}: من قبورهم إلى يوم بعثِهِم ونشورِهِم.","en":"Al-Sa'di: \"and among His signs\" showing His perfect power and His sole sovereignty, governance and oneness \"is that you see the earth humble\" — no plant in it — \"but when We send down water upon it\", the rain, \"it stirs and swells\" and then grows of every beautiful kind, so servants and lands are given life; \"indeed He who revived it is the Reviver of the dead\", from their graves to the day of their resurrection and gathering."}},{"t":"كذلك نخرج الموتى","r":[7,57,57],"q":{"bk":"saadi","w":"السعدي","s":7,"ay":57,"x":"وقوله:{كذلك نخرِجُ الموتى لعلَّكم تَذَكَّرون}؛ أي: كما أحيينا الأرض بعد موتها بالنبات كذلك نخرج الموتى من قبورهم بعدما كانوا رفاتاً متمزِّقين. وهذا استدلال واضح؛ فإنه لا فرق بين الأمرين؛ فمنكِرُ البعثِ استبعاداً له مع أنه يرى ما هو نظيره من باب العناد وإنكار المحسوسات.","en":"Al-Sa'di: \"thus We bring forth the dead, that you may remember\" — as We revived the earth after its death with plants, so We bring the dead out of their graves after they were crumbled remains; this is a clear proof, for there is no difference between the two matters; the denier of resurrection, finding it improbable while seeing its counterpart, is being stubborn and denying what can be sensed."}},{"t":"فلينظر الإنسان إلى طعامه","r":[80,24,32],"q":{"bk":"saadi","w":"السعدي","s":80,"ay":24,"x":"{24 ـ 32} ثم أرشده الله إلى النظر والتفكُّر في طعامه، وكيف وصل إليه بعدما تكرَّرت عليه طبقاتٌ عديدةٌ ويسَّره [اللَّهُ] له؛ فقال:{فلينظُرِ الإنسانُ إلى طعامه. أنَّا صَبَبۡنا الماء صَبًّا}؛ أي: أنزلنا المطر على الأرض بكثرة {ثم شَقَقۡنا الأرض} للنبات {شقًّا.","en":"Al-Sa'di: then Allah directed man to look and reflect on his food and how it reached him after many layers repeated upon it, and Allah made it easy for him; He said \"let man look at his food: that We poured water in abundance\" — We sent the rain down on the earth in great quantity — \"then We split the earth\" for plants \"in clefts\"."}},{"t":"من الشجر الأخضر ناراً","r":[36,80,80],"q":{"bk":"saadi","w":"السعدي","s":36,"ay":80,"x":"{80} ثم ذَكَرَ دليلاً ثالثاً، فقال:{الذي جَعَلَ لكم من الشَّجَرِ الأخضرِ ناراً فإذا أنتُم منه توقِدونَ}: فإذا أخرجَ النار اليابسة من الشجر الأخضرِ الذي هو في غاية الرُّطوبة مع تضادِّهما وشدَّة تخالُفِهما؛ فإخْراجُهُ الموتى من قبورِهِم مثلُ ذلك.","en":"Al-Sa'di: then He mentioned a third proof: \"He who made for you from the green tree fire, and from it you kindle\"; when He brings dry fire out of the green tree that is extremely moist, despite their being opposites and so different, then His bringing the dead out of their graves is like that."}},{"t":"الشجر يسجد لربه","r":[55,6,6],"q":{"bk":"saadi","w":"السعدي","s":55,"ay":6,"x":"{6}{والنجم والشجر يسجُدان}؛ أي: نجوم السماء وأشجار الأرض تعرِفُ ربَّها وتسجُد له وتطيع وتخضع وتنقاد لما سخَّرها له من مصالح عباده ومنافعهم.","en":"Al-Sa'di: \"and the stars and the trees prostrate\" — the stars of the sky and the trees of the earth know their Lord and prostrate to Him, obey, humble themselves and submit to what He subjected them for, of the interests and benefits of His servants."}},{"t":"وحدة الماء واختلاف الأكل","r":[13,4,4],"q":{"bk":"saadi","w":"السعدي","s":13,"ay":4,"x":"{ونُفضِّل بعضَها على بعضٍ في الأُكُل}: لوناً وطعماً ونفعاً ولذَّةً؛ فهذه أرض طيِّبة تنبت الكلأ والعشب الكثير والأشجار والزروع، وهذه أرضٌ تلاصِقُها لا تنبتُ كلأً ولا تمسك ماءً، وهذه تمسك الماء ولا تنبت الكلأ، وهذه تنبِتُ [الزروع] والأشجار ولا تنبِتُ الكلأ، وهذه الثمرةُ حلوةٌ وهذه مرَّةٌ وهذه بين ذلك؛ فهل هذا التنوُّع في ذاتها وطبيعتها أم ذلك تقدير العزيز الرحيم؟","en":"Al-Sa'di: \"and We make some of them exceed others in taste\" in colour, flavour, benefit and delight; here is good earth that grows plenty of herbage, grass, trees and crops, and next to it land that grows no herbage and holds no water, and this holds water but grows no herbage, and this grows crops and trees but no herbage; this fruit is sweet, this is bitter and this is between; is this variety in their own substance and nature, or is it the decree of the Mighty, the Merciful?"}}],"am":[{"t":"الشجرة الطيبة: كلمة التوحيد في قلب المؤمن","r":[14,24,25],"q":{"bk":"saadi","w":"السعدي","s":14,"ay":24,"x":"{25}{تؤتي أكُلَها}؛ أي: ثمرتها، {كلَّ حين بإذن ربِّها}: فكذلك شجرة الإيمان أصلُها ثابتٌ في قلب المؤمن علماً واعتقاداً، وفرعُها من الكلم الطيِّب والعمل الصالح والأخلاق المرضيَّة والآداب الحسنة في السماء دائماً، يصعَدُ إلى الله منه من الأعمال والأقوال التي تخرِجُها شجرة الإيمان، ما ينتفعُ به المؤمن وينتفع غيره، {ويضرِبُ الله الأمثالَ للناس لعلَّهم يتذكَّرون}: ما أمرهم به ونهاهم عنه؛ فإنَّ في ضرب الأمثال تقريباً للمعاني المعقولة من الأمثال المحسوسة، ويتبيَّن المعنى الذي أراده الله غاية البيان ويتَّضح غاية الوضوح، وهذا من رحمته وحسن تعليمه؛ فللَّه أتمُّ الحمد وأكمله وأعمُّه.","en":"Al-Sa'di: \"it brings forth its fruit all the time by its Lord's leave\" — so the tree of faith has its root firm in the believer's heart in knowledge and belief, and its branch of good words, righteous deeds, pleasing character and good manners is always in the sky, and from it rise to Allah deeds and words that the tree of faith produces, by which the believer and others benefit; \"and Allah sets forth parables for people so that they may remember\" what He commanded and forbade them, for parables bring rational meanings close by sensible examples, and the meaning Allah intended becomes clear to the utmost."}},{"t":"كلمة الشهادة شجرة أصلها ثابت: قول ابن عباس","r":[14,24,24],"q":{"bk":"ibnkathir","w":"ابن كثير","s":14,"ay":24,"x":"قَالَ عَلِيُّ بْنُ أَبِي طَلْحَةَ، عَنِ ابْنِ عَبَّاسٍ فِي قَوْلِهِ: ﴿مَثَلا كَلِمَةً طَيِّبَةً﴾ شَهَادَةُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، ﴿كَشَجَرَةٍ طَيِّبَةٍ﴾ وَهُوَ الْمُؤْمِنُ، ﴿أَصْلُهَا ثَابِتٌ﴾ يَقُولُ: لَا إِلَهَ إِلَّا اللَّهُ فِي قَلْبِ الْمُؤْمِنِ، ﴿وَفَرْعُهَا فِي السَّمَاءِ﴾ يَقُولُ: يُرْفَعُ بِهَا عَمَلُ الْمُؤْمِنِ إِلَى السَّمَاءِ.","en":"Ibn Kathir: Ali ibn Abi Talha narrated from Ibn Abbas on \"a parable: a good word\": the testimony that there is no god but Allah, \"like a good tree\": the believer; \"its root firm\": there is no god but Allah in the believer's heart; \"and its branches in the sky\": the believer's deed is raised by it to the sky."}},{"t":"الشجرة الخبيثة: كلمة الكفر لا قرار لها","r":[14,26,26],"q":{"bk":"saadi","w":"السعدي","s":14,"ay":26,"x":"{26} ثم ذكر ضدَّها، وهي كلمة الكفر وفروعها، فقال:{ومَثَلُ كلمةٍ خبيثة كشجرةٍ خبيثةٍ}: المأكل والمطعم، وهي شجرة الحنظل ونحوها. {اجتُثَّت}: هذه الشجرة {من فوق الأرض ما لها من قرارٍ}؛ أي:[من] ثبوت؛ فلا عروق تمسكها، ولا ثمرة صالحة تنتِجُها، بل إنْ وُجِدَ فيها ثمرةٌ؛ فهي ثمرةٌ خبيثة، كذلك كلمة الكفر والمعاصي، ليس لها ثبوتٌ نافعٌ في القلب، ولا تثمِرُ إلا كلَّ قولٍ خبيثٍ وعملٍ خبيثٍ يستضر به صاحبه، ولا ينتفعُ، ولا يصعدُ إلى الله منه عملٌ صالح، ولا ينفع نفسه، ولا ينتفع به غيره.","en":"Al-Sa'di: \"and the parable of a bad word is that of a bad tree\" — bad in food and taste, the colocynth tree and the like; \"uprooted from the surface of the earth, with no stability\"; it has no roots to hold it and no good fruit to yield, and if any fruit is found it is bad fruit; likewise the word of disbelief and sin has no useful stability in the heart and bears only every bad word and bad deed that harms its owner, no good, and no righteous deed from it rises to Allah, it benefits neither himself nor others."}},{"t":"مثل الحياة الدنيا كماء أنزلناه من السماء","r":[10,24,24],"q":{"bk":"saadi","w":"السعدي","s":10,"ay":24,"x":"{24} وهذا المثل من أحسن الأمثلة، وهو مطابقٌ لحالة الدنيا؛ فإنَّ لذَّاتها وشهواتها وجاهها ونحو ذلك يزهو لصاحبه إن زها وقتاً قصيراً؛ فإذا استكمل وتمَّ؛ اضمحلَّ وزال عن صاحبه أو زال صاحبه عنه، فأصبح صِفْرَ اليدين منها، ممتلئ القلب من همِّها وحزنها وحسرتها؛ فذلك {كماءٍ أنزلناه من السماء فاختلط به نباتُ الأرض}؛ أي: نبت فيها من كل صنفٍ وزوج بهيج، {مما يأكلُ الناس}: كالحبوب والثمار، {و} مما تأكل {الأنعامُ}: كأنواع العشب والكلأ المختلف الأصناف.","en":"Al-Sa'di: this parable is among the best and matches the state of this world; its pleasures, desires, rank and the like flourish briefly for their owner; when they are complete they fade and vanish from him or he is parted from them, leaving him empty-handed, his heart full of its worry, grief and regret; that is \"like water We sent down from the sky, so mixed with it the plants of the earth\", of every kind and beautiful pair, \"from which people eat\" like grains and fruits, \"and animals\", such as the kinds of herbage and grass of various sorts."}},{"t":"صاحب الجنتين: أعناب محفوفة بنخل","r":[18,32,34],"q":{"bk":"saadi","w":"السعدي","s":18,"ay":32,"x":"فأحدُ هذين الرجلين الكافر لنعمة الله الجليلة جعل الله له جنتين؛ أي: بستانَيْنِ حسنَيْنِ {من أعناب وحفَفۡناهما بنخل}؛ أي: في هاتين الجنتين من كل الثمرات، وخصوصاً أشرف الأشجار العنب والنخل؛ فالعنب وسطها، والنخل قد حفَّ بذلك ودار به، فحصل فيه من حسن المنظر وبهائه وبروز الشجر والنخل للشمس والرياح التي تكمُلُ بها الثمار وتنضج وتتجوهر، ومع ذلك جعل بين تلك الأشجار زَرْعاً.","en":"Al-Sa'di: one of the two men, the ingrate for Allah's great blessing, Allah gave two gardens, two beautiful orchards \"of grapevines, and We surrounded them with palm trees\": in the two gardens were all fruits, especially the noblest trees, the vine and the palm; the vine in the middle and the palm surrounding it, so there was beauty of sight and splendour, and trees and palms exposed to the sun and wind by which fruit is completed, ripens and matures; and between those trees He made crops."}},{"t":"أصحاب الجنة: اغترار بالثمر وطائف من الله","r":[68,17,20],"q":{"bk":"saadi","w":"السعدي","s":68,"ay":17,"x":"{17 ـ 18} يقول تعالى: إنَّا بَلَوْنا هؤلاء المكذِّبين بالخير، وأمهلناهم، وأمددناهم بما شئنا من مال وولدٍ وطول عمرٍ ونحو ذلك ممَّا يوافق أهواءهم، لا لكرامتهم علينا، بل ربَّما يكون استدراجاً لهم من حيثُ لا يعلمون، فاغترارهم بذلك نظيرُ اغترار أصحاب الجنَّة الذين هم فيها شركاء، حين أينعت أشجارها، وزهت ثمارها ، وآن وقت صِرامها وجزموا أنَّها في أيديهم وطوع أمرهم، وأنَّه ليس ثَمَّ مانعٌ يمنعهم منها، ولهذا أقسموا وحلفوا من غير استثناءٍ أنَّهم سيصرمونها؛ أي: يجذُّونها مصبحين، ولم يَدْروا أنَّ الله بالمرصادِ، وأنَّ العذاب سيخلفهم عليها ويبادِرُهم إليها.","en":"Al-Sa'di: Allah says \"We have tried these deniers of the good\" — We gave them respite and increased them with what We willed of wealth, children and long life that suits their desires, not out of honour for them but perhaps as a gradual drawing-in from where they do not know; their delusion is like the delusion of the owners of the garden, who were partners in it when its trees ripened and its fruit flourished and the time of its harvest came, and they were certain it was in their hands and under their command, that nothing would prevent them, so they swore without exception to pick it in the morning; they did not know that Allah is watching, and that punishment would take their place over it and hasten to it."}},{"t":"القلوب كالأرض: طيّبة تنبت وخبيثة لا تُخرج إلا نكداً","r":[7,58,58],"q":{"bk":"saadi","w":"السعدي","s":7,"ay":57,"x":"{58} ثم ذكر تفاوت الأراضي التي ينزل عليها المطر، فقال:{والبلدُ الطيِّب}؛ أي: طيب التربة والمادة، إذا نزل عليه المطر؛ {يخرج نباتُهُ}: الذي هو مستعدٌّ له {بإذن ربِّه}؛ أي: بإرادة الله ومشيئته، فليست الأسباب مستقلَّةً بوجود الأشياء حتى يأذن الله بذلك. {والذي خَبُثَ}: من الأراضي {لا يخرُجُ إلَّا نَكِداً}؛ أي: إلا نباتاً خاسًّا لا نفع فيه ولا بركة.","en":"Al-Sa'di: then He mentioned the difference in lands on which rain falls: \"and the good land\", good in soil and substance, when rain falls on it \"its vegetation comes forth\", which it is prepared for, \"by its Lord's permission\", by Allah's will; so means are not independent in bringing things into being unless Allah permits it; \"and that which is bad\" of lands \"yields nothing but scant growth\" — poor plants with no benefit or blessing."}}],"h":[{"id":"ghars","t":"غرس الشجر وزرع الزرع صدقة","x":"مَا مِنْ مُسْلِمٍ يَغْرِسُ غَرْسًا، أَوْ يَزْرَعُ زَرْعًا، فَيَأْكُلُ مِنْهُ طَيْرٌ أَوْ إِنْسَانٌ أَوْ بَهِيمَةٌ، إِلاَّ كَانَ لَهُ بِهِ صَدَقَةٌ","src":[["bukhari","2320"]],"gr":"صحيح: رواه البخاري","f":"في الحديث أن من غرس غرساً أو زرع زرعاً فأكل منه طير أو إنسان أو بهيمة كان له به صدقة؛ فبابُ الأجر فيه يتسع ليشمل ما تأكله الطيور والبهائم.","en":"No Muslim plants a tree or sows a crop, and a bird or a person or an animal eats from it, but it is a charity for him."},{"id":"nakhla","t":"من الشجر شجرة مثل المسلم وهي النخلة","x":"مِنَ الشَّجَرِ شَجَرَةٌ تَكُونُ مِثْلَ الْمُسْلِمِ، وَهْىَ النَّخْلَةُ","src":[["bukhari","5448"]],"gr":"صحيح: رواه البخاري","f":"شبّه النبي ﷺ المسلم بشجرة من الشجر، وبيّنت الرواية أنها النخلة؛ وفيه ربطٌ بين النبات وحال المؤمن.","en":"Among the trees is a tree that is like the Muslim, and it is the palm."},{"id":"khama","t":"مثل المؤمن كالخامة من الزرع","x":"مَثَلُ الْمُؤْمِنِ كَالْخَامَةِ مِنَ الزَّرْعِ تُفَيِّئُهَا الرِّيحُ مَرَّةً، وَتَعْدِلُهَا مَرَّةً، وَمَثَلُ الْمُنَافِقِ كَالأَرْزَةِ لاَ تَزَالُ حَتَّى يَكُونَ انْجِعَافُهَا مَرَّةً وَاحِدَةً","src":[["bukhari","5643"]],"gr":"صحيح: رواه البخاري","f":"ضرب النبي ﷺ المثل بالنبات في حال المؤمن وحال المنافق: خامة الزرع تميلها الريح وتعدلها، والأرزة لا تلين حتى تنقلع مرة واحدة.","en":"The likeness of the believer is that of a fresh young plant that the wind bends now and straightens again, and the likeness of the hypocrite is that of the cedar tree that stays rigid until it is uprooted all at once."},{"id":"zar","t":"رجل من أهل الجنة استأذن ربه في الزرع","x":"أَنَّ رَجُلاً مِنْ أَهْلِ الْجَنَّةِ اسْتَأْذَنَ رَبَّهُ فِي الزَّرْعِ فَقَالَ أَوَ لَسْتَ فِيمَا شِئْتَ. قَالَ بَلَى وَلَكِنِّي أُحِبُّ أَنْ أَزْرَعَ. فَأَسْرَعَ وَبَذَرَ فَتَبَادَرَ الطَّرْفَ نَبَاتُهُ وَاسْتِوَاؤُهُ وَاسْتِحْصَادُهُ وَتَكْوِيرُهُ أَمْثَالَ الْجِبَالِ فَيَقُولُ اللَّهُ تَعَالَى دُونَكَ يَا ابْنَ آدَمَ فَإِنَّهُ لاَ يُشْبِعُكَ شَىْءٌ","src":[["bukhari","7519"]],"gr":"صحيح: رواه البخاري","f":"في الحديث إثبات أن لأهل الجنة ما يشتهون حتى الزرع إن أحبّوه، وأن ابن آدم لا يشبعه شيء.","en":"A man of the people of Paradise asked his Lord's permission to farm. He said: \"Are you not in what you wish?\" He said: \"Yes, but I love to sow.\" He hurried and sowed, and in the blink of an eye its sprouting, ripening, harvest and heaping were like mountains. Allah said: \"Here you are, son of Adam, for nothing satisfies you.\""}],"ay":{"41":"وَقُلۡنَا يَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ","42":"فَأَزَلَّهُمَا ٱلشَّيۡطَٰنُ عَنۡهَا فَأَخۡرَجَهُمَا مِمَّا كَانَا فِيهِۖ وَقُلۡنَا ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرّٞ وَمَتَٰعٌ إِلَىٰ حِينٖ","267":"مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتۡ سَبۡعَ سَنَابِلَ فِي كُلِّ سُنۢبُلَةٖ مِّاْئَةُ حَبَّةٖۗ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ","883":"۞ إِنَّ ٱللَّهَ فَالِقُ ٱلۡحَبِّ وَٱلنَّوَىٰۖ يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَمُخۡرِجُ ٱلۡمَيِّتِ مِنَ ٱلۡحَيِّۚ ذَٰلِكُمُ ٱللَّهُۖ فَأَنَّىٰ تُؤۡفَكُونَ","887":"وَهُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ نَبَاتَ كُلِّ شَيۡءٖ فَأَخۡرَجۡنَا مِنۡهُ خَضِرٗا نُّخۡرِجُ مِنۡهُ حَبّٗا مُّتَرَاكِبٗا وَمِنَ ٱلنَّخۡلِ مِن طَلۡعِهَا قِنۡوَانٞ دَانِيَةٞ وَجَنَّٰتٖ مِّنۡ أَعۡنَابٖ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُشۡتَبِهٗا وَغَيۡرَ مُتَشَٰبِهٍۗ ٱنظُرُوٓاْ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَيَنۡعِهِۦٓۚ إِنَّ فِي ذَٰلِكُمۡ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ","929":"۞ وَهُوَ ٱلَّذِيٓ أَنشَأَ جَنَّٰتٖ مَّعۡرُوشَٰتٖ وَغَيۡرَ مَعۡرُوشَٰتٖ وَٱلنَّخۡلَ وَٱلزَّرۡعَ مُخۡتَلِفًا أُكُلُهُۥ وَٱلزَّيۡتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهٗا وَغَيۡرَ مُتَشَٰبِهٖۚ كُلُواْ مِن ثَمَرِهِۦٓ إِذَآ أَثۡمَرَ وَءَاتُواْ حَقَّهُۥ يَوۡمَ حَصَادِهِۦۖ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ","972":"وَيَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ فَكُلَا مِنۡ حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ","973":"فَوَسۡوَسَ لَهُمَا ٱلشَّيۡطَٰنُ لِيُبۡدِيَ لَهُمَا مَا وُۥرِيَ عَنۡهُمَا مِن سَوۡءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنۡ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيۡنِ أَوۡ تَكُونَا مِنَ ٱلۡخَٰلِدِينَ","974":"وَقَاسَمَهُمَآ إِنِّي لَكُمَا لَمِنَ ٱلنَّٰصِحِينَ","975":"فَدَلَّىٰهُمَا بِغُرُورٖۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۖ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمۡ أَنۡهَكُمَا عَن تِلۡكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيۡطَٰنَ لَكُمَا عَدُوّٞ مُّبِينٞ","1010":"وَهُوَ ٱلَّذِي يُرۡسِلُ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦۖ حَتَّىٰٓ إِذَآ أَقَلَّتۡ سَحَابٗا ثِقَالٗا سُقۡنَٰهُ لِبَلَدٖ مَّيِّتٖ فَأَنزَلۡنَا بِهِ ٱلۡمَآءَ فَأَخۡرَجۡنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِۚ كَذَٰلِكَ نُخۡرِجُ ٱلۡمَوۡتَىٰ لَعَلَّكُمۡ تَذَكَّرُونَ","1011":"وَٱلۡبَلَدُ ٱلطَّيِّبُ يَخۡرُجُ نَبَاتُهُۥ بِإِذۡنِ رَبِّهِۦۖ وَٱلَّذِي خَبُثَ لَا يَخۡرُجُ إِلَّا نَكِدٗاۚ كَذَٰلِكَ نُصَرِّفُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَشۡكُرُونَ","1387":"إِنَّمَا مَثَلُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ مِمَّا يَأۡكُلُ ٱلنَّاسُ وَٱلۡأَنۡعَٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلۡأَرۡضُ زُخۡرُفَهَا وَٱزَّيَّنَتۡ وَظَنَّ أَهۡلُهَآ أَنَّهُمۡ قَٰدِرُونَ عَلَيۡهَآ أَتَىٰهَآ أَمۡرُنَا لَيۡلًا أَوۡ نَهَارٗا فَجَعَلۡنَٰهَا حَصِيدٗا كَأَن لَّمۡ تَغۡنَ بِٱلۡأَمۡسِۚ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَتَفَكَّرُونَ","1710":"وَفِي ٱلۡأَرۡضِ قِطَعٞ مُّتَجَٰوِرَٰتٞ وَجَنَّٰتٞ مِّنۡ أَعۡنَٰبٖ وَزَرۡعٞ وَنَخِيلٞ صِنۡوَانٞ وَغَيۡرُ صِنۡوَانٖ يُسۡقَىٰ بِمَآءٖ وَٰحِدٖ وَنُفَضِّلُ بَعۡضَهَا عَلَىٰ بَعۡضٖ فِي ٱلۡأُكُلِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ","1773":"أَلَمۡ تَرَ كَيۡفَ ضَرَبَ ٱللَّهُ مَثَلٗا كَلِمَةٗ طَيِّبَةٗ كَشَجَرَةٖ طَيِّبَةٍ أَصۡلُهَا ثَابِتٞ وَفَرۡعُهَا فِي ٱلسَّمَآءِ","1774":"تُؤۡتِيٓ أُكُلَهَا كُلَّ حِينِۭ بِإِذۡنِ رَبِّهَاۗ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ","1775":"وَمَثَلُ كَلِمَةٍ خَبِيثَةٖ كَشَجَرَةٍ خَبِيثَةٍ ٱجۡتُثَّتۡ مِن فَوۡقِ ٱلۡأَرۡضِ مَا لَهَا مِن قَرَارٖ","2088":"وَإِذۡ قُلۡنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِۚ وَمَا جَعَلۡنَا ٱلرُّءۡيَا ٱلَّتِيٓ أَرَيۡنَٰكَ إِلَّا فِتۡنَةٗ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلۡمَلۡعُونَةَ فِي ٱلۡقُرۡءَانِۚ وَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَٰنٗا كَبِيرٗا","2171":"۞ وَٱضۡرِبۡ لَهُم مَّثَلٗا رَّجُلَيۡنِ جَعَلۡنَا لِأَحَدِهِمَا جَنَّتَيۡنِ مِنۡ أَعۡنَٰبٖ وَحَفَفۡنَٰهُمَا بِنَخۡلٖ وَجَعَلۡنَا بَيۡنَهُمَا زَرۡعٗا","2172":"كِلۡتَا ٱلۡجَنَّتَيۡنِ ءَاتَتۡ أُكُلَهَا وَلَمۡ تَظۡلِم مِّنۡهُ شَيۡـٔٗاۚ وَفَجَّرۡنَا خِلَٰلَهُمَا نَهَرٗا","2173":"وَكَانَ لَهُۥ ثَمَرٞ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكۡثَرُ مِنكَ مَالٗا وَأَعَزُّ نَفَرٗا","2272":"فَأَجَآءَهَا ٱلۡمَخَاضُ إِلَىٰ جِذۡعِ ٱلنَّخۡلَةِ قَالَتۡ يَٰلَيۡتَنِي مِتُّ قَبۡلَ هَٰذَا وَكُنتُ نَسۡيٗا مَّنسِيّٗا","2273":"فَنَادَىٰهَا مِن تَحۡتِهَآ أَلَّا تَحۡزَنِي قَدۡ جَعَلَ رَبُّكِ تَحۡتَكِ سَرِيّٗا","2274":"وَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا","2275":"فَكُلِي وَٱشۡرَبِي وَقَرِّي عَيۡنٗاۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلۡبَشَرِ أَحَدٗا فَقُولِيٓ إِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمٗا فَلَنۡ أُكَلِّمَ ٱلۡيَوۡمَ إِنسِيّٗا","2467":"فَوَسۡوَسَ إِلَيۡهِ ٱلشَّيۡطَٰنُ قَالَ يَٰٓـَٔادَمُ هَلۡ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلۡخُلۡدِ وَمُلۡكٖ لَّا يَبۡلَىٰ","2468":"فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ","2469":"ثُمَّ ٱجۡتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيۡهِ وَهَدَىٰ","2599":"يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي رَيۡبٖ مِّنَ ٱلۡبَعۡثِ فَإِنَّا خَلَقۡنَٰكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ مِنۡ عَلَقَةٖ ثُمَّ مِن مُّضۡغَةٖ مُّخَلَّقَةٖ وَغَيۡرِ مُخَلَّقَةٖ لِّنُبَيِّنَ لَكُمۡۚ وَنُقِرُّ فِي ٱلۡأَرۡحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٖ مُّسَمّٗى ثُمَّ نُخۡرِجُكُمۡ طِفۡلٗا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡۖ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡلَا يَعۡلَمَ مِنۢ بَعۡدِ عِلۡمٖ شَيۡـٔٗاۚ وَتَرَى ٱلۡأَرۡضَ هَامِدَةٗ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡ وَأَنۢبَتَتۡ مِن كُلِّ زَوۡجِۭ بَهِيجٖ","2692":"وَشَجَرَةٗ تَخۡرُجُ مِن طُورِ سَيۡنَآءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغٖ لِّلۡأٓكِلِينَ","2825":"۞ ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ مَثَلُ نُورِهِۦ كَمِشۡكَوٰةٖ فِيهَا مِصۡبَاحٌۖ ٱلۡمِصۡبَاحُ فِي زُجَاجَةٍۖ ٱلزُّجَاجَةُ كَأَنَّهَا كَوۡكَبٞ دُرِّيّٞ يُوقَدُ مِن شَجَرَةٖ مُّبَٰرَكَةٖ زَيۡتُونَةٖ لَّا شَرۡقِيَّةٖ وَلَا غَرۡبِيَّةٖ يَكَادُ زَيۡتُهَا يُضِيٓءُ وَلَوۡ لَمۡ تَمۡسَسۡهُ نَارٞۚ نُّورٌ عَلَىٰ نُورٖۚ يَهۡدِي ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُۚ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَٰلَ لِلنَّاسِۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ","3620":"لَقَدۡ كَانَ لِسَبَإٖ فِي مَسۡكَنِهِمۡ ءَايَةٞۖ جَنَّتَانِ عَن يَمِينٖ وَشِمَالٖۖ كُلُواْ مِن رِّزۡقِ رَبِّكُمۡ وَٱشۡكُرُواْ لَهُۥۚ بَلۡدَةٞ طَيِّبَةٞ وَرَبٌّ غَفُورٞ","3621":"فَأَعۡرَضُواْ فَأَرۡسَلۡنَا عَلَيۡهِمۡ سَيۡلَ ٱلۡعَرِمِ وَبَدَّلۡنَٰهُم بِجَنَّتَيۡهِمۡ جَنَّتَيۡنِ ذَوَاتَيۡ أُكُلٍ خَمۡطٖ وَأَثۡلٖ وَشَيۡءٖ مِّن سِدۡرٖ قَلِيلٖ","3737":"وَءَايَةٞ لَّهُمُ ٱلۡأَرۡضُ ٱلۡمَيۡتَةُ أَحۡيَيۡنَٰهَا وَأَخۡرَجۡنَا مِنۡهَا حَبّٗا فَمِنۡهُ يَأۡكُلُونَ","3738":"وَجَعَلۡنَا فِيهَا جَنَّٰتٖ مِّن نَّخِيلٖ وَأَعۡنَٰبٖ وَفَجَّرۡنَا فِيهَا مِنَ ٱلۡعُيُونِ","3784":"ٱلَّذِي جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلۡأَخۡضَرِ نَارٗا فَإِذَآ أَنتُم مِّنۡهُ تُوقِدُونَ","3849":"أَذَٰلِكَ خَيۡرٞ نُّزُلًا أَمۡ شَجَرَةُ ٱلزَّقُّومِ","3850":"إِنَّا جَعَلۡنَٰهَا فِتۡنَةٗ لِّلظَّٰلِمِينَ","3851":"إِنَّهَا شَجَرَةٞ تَخۡرُجُ فِيٓ أَصۡلِ ٱلۡجَحِيمِ","3852":"طَلۡعُهَا كَأَنَّهُۥ رُءُوسُ ٱلشَّيَٰطِينِ","3853":"فَإِنَّهُمۡ لَأٓكِلُونَ مِنۡهَا فَمَالِـُٔونَ مِنۡهَا ٱلۡبُطُونَ","3926":"وَإِنَّ يُونُسَ لَمِنَ ٱلۡمُرۡسَلِينَ","3927":"إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ","3928":"فَسَاهَمَ فَكَانَ مِنَ ٱلۡمُدۡحَضِينَ","3929":"فَٱلۡتَقَمَهُ ٱلۡحُوتُ وَهُوَ مُلِيمٞ","3930":"فَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ","3931":"لَلَبِثَ فِي بَطۡنِهِۦٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ","3932":"۞ فَنَبَذۡنَٰهُ بِٱلۡعَرَآءِ وَهُوَ سَقِيمٞ","3933":"وَأَنۢبَتۡنَا عَلَيۡهِ شَجَرَةٗ مِّن يَقۡطِينٖ","3934":"وَأَرۡسَلۡنَٰهُ إِلَىٰ مِاْئَةِ أَلۡفٍ أَوۡ يَزِيدُونَ","3935":"فَـَٔامَنُواْ فَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ","4256":"وَمِنۡ ءَايَٰتِهِۦٓ أَنَّكَ تَرَى ٱلۡأَرۡضَ خَٰشِعَةٗ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡۚ إِنَّ ٱلَّذِيٓ أَحۡيَاهَا لَمُحۡيِ ٱلۡمَوۡتَىٰٓۚ إِنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ","4456":"إِنَّ شَجَرَتَ ٱلزَّقُّومِ","4457":"طَعَامُ ٱلۡأَثِيمِ","4458":"كَٱلۡمُهۡلِ يَغۡلِي فِي ٱلۡبُطُونِ","4459":"كَغَلۡيِ ٱلۡحَمِيمِ","4600":"۞ لَّقَدۡ رَضِيَ ٱللَّهُ عَنِ ٱلۡمُؤۡمِنِينَ إِذۡ يُبَايِعُونَكَ تَحۡتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِي قُلُوبِهِمۡ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيۡهِمۡ وَأَثَٰبَهُمۡ فَتۡحٗا قَرِيبٗا","4636":"وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجِۭ بَهِيجٖ","4637":"تَبۡصِرَةٗ وَذِكۡرَىٰ لِكُلِّ عَبۡدٖ مُّنِيبٖ","4638":"وَنَزَّلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ مُّبَٰرَكٗا فَأَنۢبَتۡنَا بِهِۦ جَنَّٰتٖ وَحَبَّ ٱلۡحَصِيدِ","4639":"وَٱلنَّخۡلَ بَاسِقَٰتٖ لَّهَا طَلۡعٞ نَّضِيدٞ","4640":"رِّزۡقٗا لِّلۡعِبَادِۖ وَأَحۡيَيۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ ٱلۡخُرُوجُ","4796":"وَلَقَدۡ رَءَاهُ نَزۡلَةً أُخۡرَىٰ","4797":"عِندَ سِدۡرَةِ ٱلۡمُنتَهَىٰ","4798":"عِندَهَا جَنَّةُ ٱلۡمَأۡوَىٰٓ","4799":"إِذۡ يَغۡشَى ٱلسِّدۡرَةَ مَا يَغۡشَىٰ","4800":"مَا زَاغَ ٱلۡبَصَرُ وَمَا طَغَىٰ","4906":"وَٱلنَّجۡمُ وَٱلشَّجَرُ يَسۡجُدَانِ","4910":"وَٱلۡأَرۡضَ وَضَعَهَا لِلۡأَنَامِ","4911":"فِيهَا فَٰكِهَةٞ وَٱلنَّخۡلُ ذَاتُ ٱلۡأَكۡمَامِ","4912":"وَٱلۡحَبُّ ذُو ٱلۡعَصۡفِ وَٱلرَّيۡحَانُ","4913":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","5005":"وَأَصۡحَٰبُ ٱلۡيَمِينِ مَآ أَصۡحَٰبُ ٱلۡيَمِينِ","5006":"فِي سِدۡرٖ مَّخۡضُودٖ","5007":"وَطَلۡحٖ مَّنضُودٖ","5008":"وَظِلّٖ مَّمۡدُودٖ","5009":"وَمَآءٖ مَّسۡكُوبٖ","5029":"ثُمَّ إِنَّكُمۡ أَيُّهَا ٱلضَّآلُّونَ ٱلۡمُكَذِّبُونَ","5030":"لَأٓكِلُونَ مِن شَجَرٖ مِّن زَقُّومٖ","5031":"فَمَالِـُٔونَ مِنۡهَا ٱلۡبُطُونَ","5032":"فَشَٰرِبُونَ عَلَيۡهِ مِنَ ٱلۡحَمِيمِ","5033":"فَشَٰرِبُونَ شُرۡبَ ٱلۡهِيمِ","5041":"أَفَرَءَيۡتُم مَّا تَحۡرُثُونَ","5042":"ءَأَنتُمۡ تَزۡرَعُونَهُۥٓ أَمۡ نَحۡنُ ٱلزَّٰرِعُونَ","5043":"لَوۡ نَشَآءُ لَجَعَلۡنَٰهُ حُطَٰمٗا فَظَلۡتُمۡ تَفَكَّهُونَ","5044":"إِنَّا لَمُغۡرَمُونَ","5045":"بَلۡ نَحۡنُ مَحۡرُومُونَ","5287":"إِنَّا بَلَوۡنَٰهُمۡ كَمَا بَلَوۡنَآ أَصۡحَٰبَ ٱلۡجَنَّةِ إِذۡ أَقۡسَمُواْ لَيَصۡرِمُنَّهَا مُصۡبِحِينَ","5288":"وَلَا يَسۡتَثۡنُونَ","5289":"فَطَافَ عَلَيۡهَا طَآئِفٞ مِّن رَّبِّكَ وَهُمۡ نَآئِمُونَ","5290":"فَأَصۡبَحَتۡ كَٱلصَّرِيمِ","5742":"أَخۡرَجَ مِنۡهَا مَآءَهَا وَمَرۡعَىٰهَا","5743":"وَٱلۡجِبَالَ أَرۡسَىٰهَا","5744":"مَتَٰعٗا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ","5781":"فَلۡيَنظُرِ ٱلۡإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ","5782":"أَنَّا صَبَبۡنَا ٱلۡمَآءَ صَبّٗا","5783":"ثُمَّ شَقَقۡنَا ٱلۡأَرۡضَ شَقّٗا","5784":"فَأَنۢبَتۡنَا فِيهَا حَبّٗا","5785":"وَعِنَبٗا وَقَضۡبٗا","5786":"وَزَيۡتُونٗا وَنَخۡلٗا","5787":"وَحَدَآئِقَ غُلۡبٗا","5788":"وَفَٰكِهَةٗ وَأَبّٗا","5789":"مَّتَٰعٗا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ","6098":"وَٱلتِّينِ وَٱلزَّيۡتُونِ","6099":"وَطُورِ سِينِينَ","6100":"وَهَٰذَا ٱلۡبَلَدِ ٱلۡأَمِينِ","6101":"لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمٖ"},"nay":107,"nq":53,"nls":53};
